"""Generate libFuzzer / AFL++ harness C source from an EnrichedFinding."""
from __future__ import annotations

import re
import textwrap
from typing import Dict


_BASE_LIBFUZZER_TEMPLATE = """\
// Auto-generated by harness/fuzzer/harness_writer.py
// Finding: {finding_id} | CWE: {cwe} | Source: {target_file}:{line_start}-{line_end}
// Source agent: {agent_id} (confidence={confidence:.2f})
//
// Suggested attack surface (from enrichment):
//   {exploit_path_short}
//
// To use:
//   1. Replace TARGET_API_CALL with the real entry point of {target_function}.
//   2. Build with: ./build.sh
//   3. Run with:   ./run.sh
//
// libFuzzer entry; AFL++ persistent mode also supported via __AFL_LOOP.
#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

{includes}

int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size) {{
{body}
    return 0;
}}
"""


_CWE_BODY_TEMPLATES: Dict[str, str] = {
    "memory": """\
    if (Size < 4) return 0;
    size_t n = (size_t)Data[0] | ((size_t)Data[1] << 8)
             | ((size_t)Data[2] << 16) | ((size_t)Data[3] << 24);
    const uint8_t *payload = Data + 4;
    size_t payload_len = Size - 4;
    if (n > payload_len) n = payload_len;

    // === TARGET_API_CALL ===
    // TODO: replace with the real call into {target_function}.
    char dst[16];
    if (n > sizeof(dst) * 64) return 0;  // keep ASan reports cheap
    memcpy(dst, payload, n);  // sink: triggers ASan on overflow
    (void)dst;
""",
    "integer": """\
    if (Size < 8) return 0;
    uint32_t a = ((uint32_t)Data[0]) | ((uint32_t)Data[1] << 8)
               | ((uint32_t)Data[2] << 16) | ((uint32_t)Data[3] << 24);
    uint32_t b = ((uint32_t)Data[4]) | ((uint32_t)Data[5] << 8)
               | ((uint32_t)Data[6] << 16) | ((uint32_t)Data[7] << 24);

    // === TARGET_API_CALL ===
    // TODO: replace with the real arithmetic path in {target_function}.
    size_t total = (size_t)a * (size_t)b;  // overflow candidate
    if (total > (1U << 28)) return 0;
    void *p = malloc(total);
    if (p) {{ memset(p, 0xAA, total); free(p); }}
""",
    "injection": """\
    if (Size == 0 || Size > 4096) return 0;
    char *buf = (char *)malloc(Size + 1);
    if (!buf) return 0;
    memcpy(buf, Data, Size);
    buf[Size] = 0;

    // === TARGET_API_CALL ===
    // TODO: replace with the real injection sink ({target_function}).
    // Format-string demonstration (CWE-134):
    fprintf(stderr, buf);  // sink: format-string vuln
    free(buf);
""",
    "crypto_auth": """\
    if (Size < 16) return 0;
    // Crypto/auth findings are usually not productive to fuzz at the byte
    // level — they need protocol-aware drivers. This stub feeds bytes into
    // a placeholder so the harness still compiles. Replace with a call
    // into {target_function} that exercises the suspect primitive
    // (token validation, key check, signature verify).
    volatile uint8_t sink = 0;
    for (size_t i = 0; i < Size; i++) sink ^= Data[i];
    (void)sink;
""",
    "generic": """\
    // === TARGET_API_CALL ===
    // TODO: replace with the real entry point of {target_function}.
    if (Size > 0) {{
        volatile uint8_t s = Data[0];
        (void)s;
    }}
""",
}


_SAFE_NAME_RE = re.compile(r"[^A-Za-z0-9_]")


def _safe_name(s: str, default: str = "target_fn") -> str:
    if not s:
        return default
    cleaned = _SAFE_NAME_RE.sub("_", s)[:64]
    if not cleaned or cleaned[0].isdigit():
        cleaned = "_" + cleaned
    return cleaned or default


def _shorten(s: str, n: int = 200) -> str:
    if not s:
        return ""
    s = s.strip().replace("\n", " ").replace("\r", " ")
    return (s[: n - 3] + "...") if len(s) > n else s


def _guess_function_name(rule_id: str, file_path: str) -> str:
    if file_path:
        base = file_path.rsplit("/", 1)[-1].rsplit(".", 1)[0]
        return _safe_name(base, "target_fn")
    return _safe_name(rule_id, "target_fn")


_BUILD_SH_TEMPLATE = """\
#!/usr/bin/env bash
# Build {job_id} (libFuzzer + sanitizers).
# Requires: clang with -fsanitize=fuzzer support.
set -euo pipefail
cd "$(dirname "$0")"

CLANG=${{CLANG:-clang}}
SANITIZERS={sanitizer_flag}
CFLAGS="-O1 -g -fno-omit-frame-pointer -fsanitize=fuzzer,${{SANITIZERS}}"

# Adjust this list to include the real target sources for {target_function}.
TARGET_SRCS="{harness_filename}"

$CLANG $CFLAGS $TARGET_SRCS -o fuzz_target
echo "[build.sh] OK -> ./fuzz_target"
"""


_RUN_SH_TEMPLATE = """\
#!/usr/bin/env bash
# Run {job_id}: libFuzzer with seed corpus + time/memory budget.
set -euo pipefail
cd "$(dirname "$0")"

if [ ! -x ./fuzz_target ]; then
    echo "[run.sh] ./fuzz_target not built. Run ./build.sh first." >&2
    exit 1
fi

mkdir -p corpus crashes
# Seed in (read-only).
cp -n seeds/* corpus/ 2>/dev/null || true

# libFuzzer args: time budget, memory cap, dedup crashes, jobs=1 for determinism.
./fuzz_target \\
    -max_total_time={time_budget_s} \\
    -rss_limit_mb={memory_limit_mb} \\
    -timeout=25 \\
    -print_final_stats=1 \\
    -artifact_prefix=./crashes/ \\
    corpus seeds 2>&1 | tee fuzz.log
"""


_AFLPP_RUN_SH_TEMPLATE = """\
#!/usr/bin/env bash
# Run {job_id}: AFL++ persistent mode with seed corpus + time/memory budget.
set -euo pipefail
cd "$(dirname "$0")"

if [ ! -x ./fuzz_target ]; then
    echo "[run.sh] ./fuzz_target not built. Run ./build.sh first." >&2
    exit 1
fi

mkdir -p out
AFL_FUZZER=${{AFL_FUZZER:-afl-fuzz}}
timeout {time_budget_s}s "$AFL_FUZZER" \\
    -i seeds -o out \\
    -m {memory_limit_mb} -t 25000 \\
    -- ./fuzz_target @@
"""


_README_TEMPLATE = """\
# Fuzz job {job_id}

- finding_id: `{finding_id}`
- cwe: `{cwe}`
- source: `{target_file}:{line_start}-{line_end}`
- function (best-effort): `{target_function}`
- subagent: `{agent_id}` (confidence={confidence:.2f}, static_priority={static_priority:.2f})

## Expected crash
{expected_crash_block}

## Files
- `harness.c`  — libFuzzer entry point. **Edit TARGET_API_CALL to wire to the real {target_function}.**
- `build.sh`   — compile with clang + {sanitizer_flag} sanitizers
- `run.sh`     — run fuzzer with {time_budget_s}s budget, {memory_limit_mb}MB cap
- `seeds/`     — {seed_count} seed inputs derived from the subagent PoC stub
- `spec.json`  — machine-readable job metadata (consumed by w46 Verifier)

## Quick start
```
chmod +x build.sh run.sh
./build.sh && ./run.sh
```

Crashes will be deduplicated in `crashes/` (libFuzzer) or `out/default/crashes/` (AFL++).
Pipe `crashes/*` back to `harness.fuzzer.crash_triage.CrashTriage` to produce `CrashRecord`s
for the w46 Verifier subagent.

## Exploit path (from enriched finding)
{exploit_path}
"""


def _sanitizer_flag(sanitizers) -> str:
    flag = ",".join(s for s in sanitizers if s in ("address", "undefined", "memory", "thread"))
    if not flag:
        flag = "address,undefined"
    return flag


def _normalize_sanitizers(sanitizers):
    out = []
    for s in (sanitizers or []):
        s = s.lower().strip()
        if s in ("asan", "address"):
            out.append("address")
        elif s in ("ubsan", "undefined"):
            out.append("undefined")
        elif s in ("msan", "memory"):
            out.append("memory")
        elif s in ("tsan", "thread"):
            out.append("thread")
    if not out:
        out = ["address", "undefined"]
    return out


def _expected_crash_block(expected: dict) -> str:
    if not expected:
        return "(unknown — verifier should accept any sanitizer crash)"
    lines = ["```"]
    for k, v in expected.items():
        lines.append(f"{k}: {v}")
    lines.append("```")
    return "\n".join(lines)


class HarnessWriter:
    """Render a libFuzzer / AFL++ harness package from an EnrichedFinding."""

    def __init__(self, fuzzer: str = "libfuzzer", time_budget_s: int = 600,
                 memory_limit_mb: int = 2048):
        if fuzzer not in ("libfuzzer", "aflpp"):
            raise ValueError(f"Unsupported fuzzer: {fuzzer}")
        self.fuzzer = fuzzer
        self.time_budget_s = time_budget_s
        self.memory_limit_mb = memory_limit_mb

    def render_files(self, enriched: dict) -> Dict[str, str]:
        """Return {filename: content} for the harness package.

        Caller writes them to disk and adds the seed corpus + spec.json separately.
        """
        cwe_class = self._infer_cwe_class(enriched)
        body = _CWE_BODY_TEMPLATES.get(cwe_class, _CWE_BODY_TEMPLATES["generic"])

        target_function = _guess_function_name(
            enriched.get("rule_id", ""), enriched.get("file_path", ""))

        body = body.format(target_function=target_function)

        includes = ""
        # Hint: include a few common headers — guards behind macros so we don't
        # break compilation if the system lacks them. The user will adjust.
        if cwe_class in ("memory", "integer"):
            includes = "// Add target headers here, e.g. #include \"target_api.h\""

        sanitizers_norm = _normalize_sanitizers(enriched.get("sanitizers"))
        sanitizer_flag = _sanitizer_flag(sanitizers_norm)

        line_start = int(enriched.get("line_start", 0) or 0)
        line_end = int(enriched.get("line_end", line_start) or line_start)

        harness_c = _BASE_LIBFUZZER_TEMPLATE.format(
            finding_id=enriched.get("finding_id", "unknown"),
            cwe=enriched.get("cwe", "unknown"),
            target_file=enriched.get("file_path", "unknown"),
            line_start=line_start,
            line_end=line_end,
            agent_id=enriched.get("agent_id", "unknown"),
            confidence=float(enriched.get("confidence", 0.0) or 0.0),
            target_function=target_function,
            exploit_path_short=_shorten(enriched.get("exploit_path", ""), 200),
            includes=includes,
            body=body,
        )

        job_id = enriched.get("finding_id", "job")[:12]
        build_sh = _BUILD_SH_TEMPLATE.format(
            job_id=job_id,
            sanitizer_flag=sanitizer_flag,
            harness_filename="harness.c",
            target_function=target_function,
        )
        run_template = _RUN_SH_TEMPLATE if self.fuzzer == "libfuzzer" else _AFLPP_RUN_SH_TEMPLATE
        run_sh = run_template.format(
            job_id=job_id,
            time_budget_s=self.time_budget_s,
            memory_limit_mb=self.memory_limit_mb,
        )

        readme = _README_TEMPLATE.format(
            job_id=job_id,
            finding_id=enriched.get("finding_id", "unknown"),
            cwe=enriched.get("cwe", "unknown"),
            target_file=enriched.get("file_path", "unknown"),
            line_start=line_start,
            line_end=line_end,
            target_function=target_function,
            agent_id=enriched.get("agent_id", "unknown"),
            confidence=float(enriched.get("confidence", 0.0) or 0.0),
            static_priority=float(enriched.get("static_priority", 0.0) or 0.0),
            sanitizer_flag=sanitizer_flag,
            time_budget_s=self.time_budget_s,
            memory_limit_mb=self.memory_limit_mb,
            seed_count=int(enriched.get("seed_count", 0) or 0),
            expected_crash_block=_expected_crash_block(enriched.get("expected_crash") or {}),
            exploit_path=enriched.get("exploit_path", "(none)"),
        )

        return {
            "harness.c": harness_c,
            "build.sh": build_sh,
            "run.sh": run_sh,
            "README.md": readme,
            "_target_function": target_function,
            "_sanitizers": ",".join(sanitizers_norm),
        }

    def _infer_cwe_class(self, enriched: dict) -> str:
        agent = enriched.get("agent_id", "").lower()
        if agent == "sa1":
            return "memory"
        if agent == "sa2":
            return "integer"
        if agent == "sa3":
            return "injection"
        if agent == "sa4":
            return "crypto_auth"
        cwe = (enriched.get("cwe") or "").upper()
        if cwe in ("CWE-119", "CWE-120", "CWE-122", "CWE-125", "CWE-416",
                   "CWE-476", "CWE-415", "CWE-401"):
            return "memory"
        if cwe in ("CWE-190", "CWE-191", "CWE-369", "CWE-197", "CWE-680"):
            return "integer"
        if cwe in ("CWE-89", "CWE-78", "CWE-611", "CWE-918", "CWE-639",
                   "CWE-134", "CWE-73"):
            return "injection"
        if cwe in ("CWE-326", "CWE-327", "CWE-330", "CWE-798", "CWE-287", "CWE-311"):
            return "crypto_auth"
        return "generic"
